class Solution {
public:
    string smallestEquivalentString(string s1, string s2, string baseStr) {
        vector<int> parent(26);
        iota(parent.begin(), parent.end(), 0);

        auto find = [&](auto& self, int i) -> int {
            if (parent[i] != i) parent[i] = self(self, parent[i]);
            return parent[i];
        };

        auto unite = [&](int i, int j) {
            int ri = find(find, i), rj = find(find, j);
            if (ri != rj) {
                if (ri < rj) parent[rj] = ri;
                else parent[ri] = rj;
            }
        };

        for (int i = 0; i < (int)s1.size(); ++i) {
            unite(s1[i] - 'a', s2[i] - 'a');
        }

        string res = baseStr;
        for (int i = 0; i < (int)res.size(); ++i) {
            res[i] = 'a' + find(find, res[i] - 'a');
        }
        return res;
    }
};

class Solution {
    public String smallestEquivalentString(String s1, String s2, String baseStr) {
        int[] parent = new int[26];
        for (int i = 0; i < 26; ++i) parent[i] = i;

        for (int i = 0; i < s1.length(); ++i) {
            union(parent, s1.charAt(i) - 'a', s2.charAt(i) - 'a');
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < baseStr.length(); ++i) {
            int root = find(parent, baseStr.charAt(i) - 'a');
            sb.append((char) ('a' + root));
        }
        return sb.toString();
    }

    private int find(int[] parent, int i) {
        if (parent[i] != i) parent[i] = find(parent, parent[i]);
        return parent[i];
    }

    private void union(int[] parent, int i, int j) {
        int ri = find(parent, i), rj = find(parent, j);
        if (ri != rj) {
            if (ri < rj) parent[rj] = ri;
            else parent[ri] = rj;
        }
    }
}

var smallestEquivalentString = function(s1, s2, baseStr) {
    const parent = Array.from({ length: 26 }, (_, i) => i);

    const find = (i) => {
        if (parent[i] !== i) parent[i] = find(parent[i]);
        return parent[i];
    };

    const union = (i, j) => {
        const ri = find(i), rj = find(j);
        if (ri !== rj) {
            if (ri < rj) parent[rj] = ri;
            else parent[ri] = rj;
        }
    };

    for (let i = 0; i < s1.length; i++) {
        union(s1.charCodeAt(i) - 97, s2.charCodeAt(i) - 97);
    }

    return baseStr.split('').map(c => String.fromCharCode(find(c.charCodeAt(0) - 97) + 97)).join('');
};
